answer.sql:
SELECT 1.0 * COUNT(DISTINCT CASE WHEN t.class IS NULL AND CAST(strftime('%Y', c.birthday_bio) AS INTEGER) <= 1975 THEN c.bioguide_id END) / COUNT(DISTINCT c.bioguide_id) AS percentage
FROM current AS c
JOIN "current-terms" AS t ON t.bioguide = c.bioguide_id;

tool_arguments.sql:
WITH legislators AS (
 SELECT c.bioguide_id bioguide,t.type FROM current c JOIN "current-terms" t ON t.bioguide=c.bioguide_id WHERE c.gender_bio='F' AND strftime('%Y',c.birthday_bio) BETWEEN '1930' AND '1970'
 UNION
 SELECT h.bioguide_id,t.type FROM historical h JOIN "historical-terms" t ON t.bioguide=h.bioguide_id WHERE h.gender_bio='F' AND strftime('%Y',h.birthday_bio) BETWEEN '1930' AND '1970'
) SELECT type,COUNT(*) AS number FROM legislators GROUP BY type;

